import heapq

def match(orders):
    trades = []
    buy_heap = []  # entries (-price, seq, id) for buy side
    sell_heap = []  # entries (price, seq, id) for sell side
    book = {}  # id -> [side, price, qty]
    seq_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        seq = seq_counter
        seq_counter += 1
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                neg_price, s_seq, s_id = sell_heap[0]
                if s_id not in book:
                    heapq.heappop(sell_heap)
                    continue
                s_side, s_price, s_qty = book[s_id]
                if typ != 'market' and price is not None and s_price > price:
                    break
                trade_qty = min(remaining, s_qty)
                trades.append([oid, s_id, s_price, trade_qty])
                remaining -= trade_qty
                s_qty -= trade_qty
                if s_qty == 0:
                    del book[s_id]
                    heapq.heappop(sell_heap)
                else:
                    book[s_id][2] = s_qty

            if remaining > 0 and typ == 'limit':
                book[oid] = ['buy', price, remaining]
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # side == 'sell'
            while remaining > 0 and buy_heap:
                neg_price, b_seq, b_id = buy_heap[0]
                if b_id not in book:
                    heapq.heappop(buy_heap)
                    continue
                b_side, b_price, b_qty = book[b_id]
                if typ != 'market' and price is not None and b_price < price:
                    break
                trade_qty = min(remaining, b_qty)
                trades.append([b_id, oid, b_price, trade_qty])
                remaining -= trade_qty
                b_qty -= trade_qty
                if b_qty == 0:
                    del book[b_id]
                    heapq.heappop(buy_heap)
                else:
                    book[b_id][2] = b_qty

            if remaining > 0 and typ == 'limit':
                book[oid] = ['sell', price, remaining]
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

